const { RestClientV5 } = require("bybit-api");

const client = new RestClientV5({
  key: process.env.BYBIT_API_KEY,
  secret: process.env.BYBIT_API_SECRET,
  testnet: false
});

async function test() {
  const balance = await client.getWalletBalance({
    accountType: "UNIFIED"
  });
  console.log(balance);
}

test();
